/**
 * The measured advances of the bundled faces (22.2), for `text.ts`.
 *
 * Generated by `npm run build:fonts` from the same woff2 files the browser
 * renders, so a pair is measured in the face it is drawn in. That is the lesson
 * of D1, where fitting with one face and rendering another overflowed three
 * slides in four, and the reason every pair must have an entry here (the types
 * in `pairs.ts` refuse an id that has none).
 *
 * Advances are synchronous and small (about 30KB gzipped for every weight of
 * every family). Kerning is a refinement, loaded per family with
 * `loadKerning`: without it a line measures slightly long, the safe direction.
 *
 * Pure: no DOM, so Node and the browser measure identically.
 */
import advances from "../render/fonts/advances.json" with { type: "json" };

type WeightMetrics = { adv: number[]; scripts: Record<string, number>; missing: number };
type FamilyMetrics = { family: string; weights: Record<string, WeightMetrics> };

const DATA = advances as unknown as {
  chars: string;
  families: Record<string, FamilyMetrics>;
  fallbacks: Record<"cyrillic" | "greek" | "latin" | "arabic" | "hebrew" | "emoji" | "cjk", number>;
};

/** Every measured family, by the id a layer stores. */
export const MEASURED = DATA.families;
export type MeasuredId = keyof typeof MEASURED & string;

export const FALLBACK_ADVANCE = DATA.fallbacks;

/** Character → index into `adv`. */
const INDEX = new Map<string, number>([...DATA.chars].map((ch, i) => [ch, i]));

export const isMeasured = (id: string | undefined): boolean => Boolean(id && MEASURED[id]);

export const weightsOf = (id: string): number[] =>
  Object.keys(MEASURED[id]?.weights ?? {})
    .map(Number)
    .sort((a, b) => a - b);

/**
 * The weight the browser will actually use, by the CSS font-matching rules.
 *
 * `LayerView` turns synthesis of bold off for bundled faces, so a 700 asked of
 * a family that ships 400 and 900 is drawn in one of those, and measurement has
 * to pick the same one or it measures a face nobody sees.
 */
export function matchWeight(available: readonly number[], desired: number): number {
  if (available.length === 0) return desired;
  if (available.includes(desired)) return desired;
  const asc = [...available].sort((a, b) => a - b);
  const below = asc.filter((w) => w < desired).reverse();
  const above = asc.filter((w) => w > desired);
  if (desired >= 400 && desired <= 500) {
    const upTo500 = above.filter((w) => w <= 500);
    const rest = above.filter((w) => w > 500);
    return upTo500[0] ?? below[0] ?? rest[0] ?? desired;
  }
  if (desired < 400) return below[0] ?? above[0] ?? desired;
  return above[0] ?? below[0] ?? desired;
}

/* ── kerning ──────────────────────────────────────────────────────────────── */

const kerning = new Map<string, Record<string, Record<string, number>>>();
const loaders = import.meta.glob<{ default: Record<string, Record<string, number>> }>("../render/fonts/kern/*.json");

/** Loads the kerning of these families, once each. Unknown ids are ignored. */
export async function loadKerning(ids: readonly (string | undefined)[]): Promise<void> {
  await Promise.all(
    [...new Set(ids)].map(async (id) => {
      if (!id || kerning.has(id) || !MEASURED[id]) return;
      const load = loaders[`../render/fonts/kern/${id}.json`];
      if (!load) return;
      kerning.set(id, (await load()).default);
    }),
  );
}

export const kerningLoaded = (id: string): boolean => kerning.has(id);

/* ── reading ──────────────────────────────────────────────────────────────── */

export type Face = {
  /** Advance of a character in em, or undefined when it is not a Latin character this face measures. */
  advance(ch: string): number | undefined;
  /** Kerning between two characters in em; 0 when unknown or unloaded. */
  kern(a: string, b: string): number;
  /** The face's own average for a script it covers, in em. */
  script(name: string): number | undefined;
};

const faces = new Map<string, Face>();

/** The face for a family and a requested weight, or null for a family not bundled. */
export function faceFor(id: string | undefined, weight = 400): Face | null {
  if (!id) return null;
  const fam = MEASURED[id];
  if (!fam) return null;
  const w = matchWeight(weightsOf(id), weight);
  const key = `${id}:${w}`;
  const hit = faces.get(key);
  if (hit) return hit;
  const m = fam.weights[String(w)];
  if (!m) return null;
  const face: Face = {
    advance: (ch) => {
      const i = INDEX.get(ch);
      return i === undefined ? undefined : (m.adv[i] ?? 0) / 1000;
    },
    kern: (a, b) => (kerning.get(id)?.[String(w)]?.[a + b] ?? 0) / 1000,
    script: (name) => (m.scripts[name] === undefined ? undefined : m.scripts[name]! / 1000),
  };
  faces.set(key, face);
  return face;
}
